import React,{useState} from "react";
import {createRoot} from "react-dom/client";
import "../../src/styles.css";
import {Button} from "../../src/shared/ui";
import {FieldRenderer} from "../../src/lowcode/FieldRenderer";
import {FieldEventSettings} from "../../src/lowcode/FieldEventSettings";
import {validateValues,type TableSchema} from "../../src/lowcode/field-model";
import type {AutomationConnector} from "../../src/lowcode/automation-model";
const table="10000000-0000-4000-8000-000000000001",version="10000000-0000-4000-8000-000000000002",connector="10000000-0000-4000-8000-000000000003",record="10000000-0000-4000-8000-000000000004";
const completed:string[]=[],calls:{event:string;body:Record<string,unknown>}[]=[],failures=new Set<string>(),originalFetch=window.fetch;
(window as unknown as {eventFixture:unknown}).eventFixture={calls,completed};
window.fetch=async(input,init)=>{const path=new URL(String(input),location.origin).pathname;if(path.includes("/field-events/")){const body=JSON.parse(String(init?.body)),event=path.split("/").at(-1)!;calls.push({event,body});const code=body.data.code;await new Promise(resolve=>setTimeout(resolve,code==="SLOW"?1100:50));completed.push(String(code??event));if(code==="FAIL"&&!failures.has(body.requestKey)){failures.add(body.requestKey);return new Response(JSON.stringify({message:"查询服务暂不可用，请重试"}),{status:503,headers:{"Content-Type":"application/json"}});}return new Response(JSON.stringify({values:event==="customerLookup"?{name:`客户 ${code}`,amount:code==="SLOW"?100:200}:{note:`人工名称已查询：${body.data.name}`}}),{headers:{"Content-Type":"application/json"}});}if(path==="/api/v1/me")return new Response(JSON.stringify({id:record,displayName:"验收成员",username:"fixture",enabled:true}),{headers:{"Content-Type":"application/json"}});return originalFetch(input,init);};
const initial:Record<string,unknown>={code:"INIT",name:"初始名称"};
const definition:TableSchema={name:"客户查询表",description:"字段变化调用查询连接器，保留手工编辑",fields:[{id:"code",label:"客户编码",type:"text",defaultValue:"INIT"},{id:"name",label:"客户名称",type:"text"},{id:"amount",label:"参考金额",type:"number"},{id:"note",label:"查询备注",type:"text"}],fieldEvents:[{id:"customerLookup",name:"按编码查询客户",sourceFieldId:"code",connectorId:connector,inputs:{query:"code"},outputs:{name:"body.name",amount:"body.amount"}},{id:"nameLookup",name:"名称补充查询",sourceFieldId:"name",connectorId:connector,inputs:{name:"name"},outputs:{note:"body.note"}}]};
const connectors:AutomationConnector[]=[{id:connector,appId:table,name:"客户查询服务",url:"https://query.example/api",method:"POST",enabled:true,revision:0}];
function Fixture(){const [schema,setSchema]=useState(definition),[values,setValues]=useState(initial),[busy,setBusy]=useState(false),[errors,setErrors]=useState<Record<string,string>>({}),[mode,setMode]=useState("create"),[key,setKey]=useState(0);return <main className="mx-auto max-w-5xl space-y-5 p-4 sm:p-6"><div className="flex flex-wrap items-center gap-3"><label className="text-sm">填写入口<select aria-label="填写入口" value={mode} onChange={event=>{setMode(event.target.value);setKey(value=>value+1);}} className="ml-2 rounded-lg border border-border bg-background px-3 py-2"><option value="create">正式新增</option><option value="edit">正式编辑</option><option value="design">设计预览</option><option value="change">审批填写</option><option value="share">分享填写</option></select></label><Button disabled={busy} onClick={()=>setErrors(validateValues(schema,values))}>验证保存</Button><span data-testid="busy">{busy?"正在读取字段数据…":"可保存"}</span></div><FieldRenderer key={key} schema={schema} value={values} onChange={setValues} directory={{people:[],units:[],positions:[]}} errors={errors} mode={mode==="edit"?"edit":"create"} originalValue={mode==="edit"?initial:undefined} onResolvingChange={setBusy} fileContext={{tableId:table,versionId:version,...(mode==="edit"?{recordId:record,recordRevision:3}:{}),...(mode==="design"?{design:true}:{}),...(mode==="change"?{changeId:record}:{}),...(mode==="share"?{shareToken:"fixture"}: {})}}/><FieldEventSettings schema={schema} onChange={setSchema} connectors={connectors}/><pre data-testid="values" className="overflow-auto rounded-xl bg-muted p-3 text-xs">{JSON.stringify(values,null,2)}</pre><pre data-testid="errors" className="text-xs text-destructive">{JSON.stringify(errors,null,2)}</pre><pre data-testid="schema" className="max-h-48 overflow-auto rounded-xl bg-muted p-3 text-xs">{JSON.stringify(schema,null,2)}</pre></main>;}
const root=createRoot(document.getElementById("root")!);root.render(<Fixture/>);if(import.meta.hot)import.meta.hot.dispose(()=>{root.unmount();window.fetch=originalFetch;});
